head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setCellMaxLength]<br/>inputType=\"custom\" 인 Column 의 특정 Body Cell 에 입력 가능한 최대 길이를 설정합니다.",
    "validation" : [
        "특정 Cell 의 inputType 속성이 'text', 'textarea', 'textImage', 'secret' 값이어야 동작합니다.",
        "rowIndex(필수) 파라미터로 입력 가능한 최대 길이를 설정하려는 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "rowIndex(필수) 파라미터의 Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정됩니다.",
        "columnInfo(필수) 파라미터로 입력 가능한 최대 길이를 설정하려는 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "maxLength(필수) 파라미터로 한 문자의 길이를 1 로 계산(다국어 포함)하여 입력 가능한 최대 길이를 숫자로 설정할 수 있어야 합니다.",
        "maxLength(필수) 파라미터는 dataType='float' 이면 '.' 문자를 기준으로 정수부와 소수부의 최대 길이를 각각 설정할 수 있습니다.",
        "maxLength(필수) 파라미터는 '.' 기준 정수부에 '*' 설정하거나 생략 시 정수부 입력 제한이 없습니다.",
        "maxLength(필수) 파라미터는 '.' 기준 소수부에 '*' 또는 '-1' 설정 시 소수부 입력 제한이 없습니다.",
        "maxLength(필수) 파라미터는 '.' 문자 없이 숫자만 설정 시 정수부 최대 길이로 적용되고 소수부는 입력할 수 없습니다.",
        "maxLength(필수) 파라미터는 '*' 또는 '*.' 설정 시 정수부만 제한 없이 입력할 수 있습니다.",
        "maxLength(필수) 파라미터는 '.' 문자만 설정 시 전체 입력이 제한됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] 4개 Body 컬럼 모두 inputType=custom + typeGetter(con_inputType 값), col1(인덱스 1) 은 숨김. col3(인덱스 3) 은 dataType=float.\n[절차] (필요시) con_inputType 선택 -> Target 재생성 -> rowIndex / columnInfo / maxLength 선택 -> setCellMaxLength 실행 -> 해당 셀 더블클릭(편집모드) -> 값 입력 -> 다른 곳 클릭(포커스아웃).\n[확인] 편집 종료(onafteredit) 시 maxLength 초과분이 잘려 셀에 표시된 값이 리턴창에 출력된다."', '', 'label1');

    // dataList 생성 + 초기값 바인딩 (maxLength 가 제한할 셀의 원본 데이터)
    //  ※ createBasicDataList 는 col1~col4 (4컬럼) 스키마만 생성하므로 5컬럼 이상은 데이터가 유실됨([createDynamicDataList 4col limit]).
    //  ※ Body custom 컬럼 id 가 dataList 컬럼(col1~col4)과 일치해야 셀 편집 가능(불일치 시 자동 readOnly).
    $c.gcm.createBasicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON([
        { "col1": "1234567890", "col2": "9876543210", "col3": "1112223334", "col4": "1234567.8901" },
        { "col1": "2233445566", "col2": "1029384756", "col3": "5566778899", "col4": "7654321.0987" },
        { "col1": "9081726354", "col2": "1213141516", "col3": "3141592653", "col4": "9998887.7766" },
        { "col1": "4455667788", "col2": "2718281828", "col3": "1414213562", "col4": "1357913.5797" }
    ]);

    // target 생성
    //  4개 Body 컬럼 모두 inputType=custom + typeGetter 로 Cell inputType=con_inputType(기본 text) 구성.
    //   col0(idx0) / col1(idx1, ★ setColumnVisible(1,false) 로 숨김 -> 인덱스는 1 유지) / col2(idx2) / col3(idx3, dataType=float)
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" ev:onafteredit="scwin.target1_onafteredit" style="width:680px;height:200px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="170" inputType="text" id="hcol1" value="col0 (custom)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol2" value="col1 (숨김)"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="hcol3" value="col2 (custom)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="col3 (float)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="170" inputType="custom" id="col1" dataList="col1" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col2" dataList="col2" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="170" inputType="custom" id="col3" dataList="col3" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '<w2:column width="*" inputType="custom" id="col4" dataList="col4" dataType="float" typeGetter="scwin.target1_textTypeGetter"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // ★ 두번째 Column(인덱스 1) 을 숨김 -> "숨겨진 Column 도 포함하여 인덱스가 설정" 검증용
    scwin.target1.setColumnVisible(1, false);
}



// 모든 custom 컬럼의 Cell inputType 을 con_inputType 선택값으로 구성한다.
//  @validation1 검증용 : allow-list(text/textarea/input/textImage/secret) 이면 setCellMaxLength 동작,
//                        그 외(number 등) 이면 "Invalid cell input type" 로 미동작(false) 됨을 확인한다.
//  ※ con_inputType 변경 후에는 'Target 재생성' 을 클릭해야 grid 가 새 inputType 으로 다시 그려진다.
scwin.target1_textTypeGetter = function (info) {
    let it = (typeof con_inputType !== 'undefined' && con_inputType.getValue()) ? con_inputType.getValue() : 'text';
    // textImage 셀은 viewType/imageSrc 가 있어야 셀에 이미지(아이콘)가 렌더된다.
    let opts = (it === 'textImage') ? { viewType: 'icon', imageSrc: '/cm/images/base/ico_grid_del.svg' } : {};
    return { id: 'cell_' + it + '_' + info.rowIndex + '_' + info.colIndex, inputType: it, options: opts };
};



// setCellMaxLength 실행 : 특정 셀에 최대 입력 길이를 설정 (3인자, 전제 미충족 시 false)
//  maxLength 가 '.' 또는 '*' 포함 OR dataType=float 이면 float 문법(문자열), 아니면 순수 숫자(Number).
//  적용 여부는 해당 셀을 더블클릭(편집모드) -> 값 입력 -> 포커스아웃 시 onafteredit 에서 표시값으로 확인한다.
scwin.btn_setCellMaxLength_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let columnInfo = Number(par_columnInfo.getValue());
    let rawMax = par_maxLength.getValue();

    let isFloatFormat = (rawMax.indexOf(".") !== -1 || rawMax.indexOf("*") !== -1);
    let maxLengthVal = isFloatFormat ? rawMax : Number(rawMax);

    let ret = scwin.target1.setCellMaxLength(rowIndex, columnInfo, maxLengthVal);

    wf_body_bottom.getObj("scwin").setReturnValue(
        "setCellMaxLength(" + rowIndex + ", " + columnInfo + ", " + (isFloatFormat ? "'" + rawMax + "'" : rawMax) + ")"
        + (ret === false ? " 미동작(false)" : " 적용")
        + " | 셀 더블클릭 -> 값 입력 -> 포커스아웃 시 표시값 출력");
}



// 셀 편집모드 종료(포커스아웃) 시 발생. maxLength 초과분이 잘려 셀에 표시된 값을 리턴창에 출력한다.
//  onafteredit @param : (rowIndex, columnIndex, value) 위치 인자. 표시값은 getCellDisplayData 로 조회.
scwin.target1_onafteredit = function (rowIndex, columnIndex, value) {
    let shown = scwin.target1.getCellDisplayData(rowIndex, columnIndex);
    wf_body_bottom.getObj("scwin").setReturnValue(
        "셀(" + rowIndex + "," + columnIndex + ") 표시값 : " + shown);
}
